scripts.modexp:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']
    result = pow(base, exp, mod)
    return float(result)

scripts.factorial_mod:
def solve(inputs: dict) -> float:
    n = inputs['N']
    mod = inputs['MOD']

    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod

    return float(result)

